content.text:
        bool absent_seen = false;
        int present = 0;
        for (int i = 0; i < slots; ++i) {
            uint64_t v = rec_get(w, p + 32 * i, 32);
            if (v == IMAGE_ABSENT_CHILD) { absent_seen = true; continue; }
            if (absent_seen) return false;  // present children come first
            uint64_t st = (v >> 6) & 0xF;
            if (st >= RAM_NUM) return false;
            VEdge e;
            e.key = static_cast<uint32_t>(v & 0x3F);
            e.stage = static_cast<uint32_t>(st);
            e.cell = static_cast<uint32_t>((v >> 10) & IMAGE_CELLS_MAX);
            e.bulk_child = false;
            n.edges.push_back(e);
            ++present;
        }
        if (slots == 2 && present > 2) return false;
        if (slots == 6 && (present < 3 || present > 6)) return false;
        return true;
    }

    bool decode_type3(const std::bitset<256>& w, int off, VNode& n) {
        uint64_t bulk = rec_get(w, off + OFF_BULK_BMP, OFF_BULK_BMP_W);
        uint64_t base = rec_get(w, off + OFF_BULK_BASE, OFF_BULK_BASE_W);
        uint64_t bstage = rec_get(w, off + OFF_BULK_STAGE, OFF_BULK_STAGE_W);
        if (bstage >= RAM_NUM) return false;
        uint32_t nb = static_cast<uint32_t>(__builtin_popcountll(bulk));
        if (nb < 4) return false;             // the rest are direct, at most three
        if (bstage >= n.stage) return false;  // bulk children live on a lower stage
        if (base % 2 != 0) return false;
        if (base + 2ULL * nb > d_.cells[bstage]) return false;
        std::vector<VEdge> direct = n.edges;  // the at most three direct slots
        uint32_t rank = 0;
        std::vector<VEdge> all;
        for (uint32_t pos = 0; pos < 64; ++pos) {
            if (!(bulk & (1ULL << pos))) continue;
            VEdge e;
            e.key = pos;
            e.stage = static_cast<uint32_t>(bstage);
            e.cell = static_cast<uint32_t>(base + 2ULL * rank);
            e.bulk_child = true;
            all.push_back(e);
            ++rank;
        }
        for (size_t i = 0; i < direct.size(); ++i) {
            if (bulk & (1ULL << direct[i].key)) return false;  // keys are disjoint
            all.push_back(direct[i]);
        }
        std::stable_sort(all.begin(), all.end(), [](const VEdge& a, const VEdge& b) { return a.key < b.key; });
        if (all.size() < 7 || all.size() > 64) return false;
        n.edges = all;
        return true;
    }

    bool dictionary_ok() {
        std::set<uint64_t> used_patterns;
        std::vector<std::pair<uint32_t, uint32_t> > spans;
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const VNode& n = nodes_[i];
            if (n.type == 4 || n.type == 5) continue;
            if (n.bitmap_id >= d_.bitmaps.size()) return false;
            uint64_t pattern = d_.bitmaps[n.bitmap_id];
            uint32_t cnt = static_cast<uint32_t>(__builtin_popcountll(pattern & ~1ULL));
            if (cnt != n.ni_len) return false;
            used_patterns.insert(pattern);
            if (cnt > 0) spans.push_back(std::make_pair(n.ni_base, cnt));
        }
        if (used_patterns.size() != d_.bitmaps.size()) return false;  // every pattern is used
        for (size_t i = 0; i < d_.bitmaps.size(); ++i) {
            if (used_patterns.find(d_.bitmaps[i]) == used_patterns.end()) return false;
        }
        std::sort(spans.begin(), spans.end());
        uint64_t cursor = 0;
        for (size_t i = 0; i < spans.size(); ++i) {
            if (spans[i].first != cursor) return false;  // disjoint, no holes
            cursor += spans[i].second;
        }
        if (cursor != d_.nexthops.size()) return false;  // covers the complete NI vector
        return true;
    }

    bool fronts_complete() {
        std::set<uint64_t> k16, k64;
        bool any0 = false;
        for (size_t i = 0; i < prefixes_.size(); ++i) {
            const FibPfx& p = prefixes_[i];
            if (p.len <= 16) any0 = true;
            else if (p.len <= 64) k16.insert(p.hi >> 48);
            else k64.insert(p.hi);
        }
        if (any0 != have_root_) return false;
        if (roots16_.size() != k16.size()) return false;
        for (size_t i = 0; i < roots16_.size(); ++i) {
            if (k16.find(roots16_[i].first) == k16.end()) return false;
        }
        if (roots64_.size() != k64.size()) return false;
        for (size_t i = 0; i < roots64_.size(); ++i) {
            if (k64.find(roots64_[i].first) == k64.end()) return false;
        }
        return true;
    }

    bool bmps_ok(const Fib& fib) {
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const VNode& n = nodes_[i];
            uint32_t want = fib.lookup_upto(n.rhi, n.rlo, n.depth);
            uint32_t field = (want == FIB_NO_HOP) ? BMP_NULL_VALUE : want;
            if (n.bmp != field) return false;
        }
        return true;
    }

    const ImageData& d_;
    std::vector<std::vector<uint8_t> > used_;
    std::vector<VNode> nodes_;
    std::vector<FibPfx> prefixes_;
    std::vector<std::pair<uint64_t, uint32_t> > roots16_, roots64_;
    bool have_root_ = false;
};

